'use strict';
function subnetHTML(){return `<section class="experiment"><h2>给一个地址，找到它的网络。</h2><p class="sub">IPv4 按位与运算：网络地址 = IP 地址 AND 子网掩码。</p><form id="subnet-form" class="lab-controls"><label>IPv4 地址<input id="ip" value="192.168.10.130" required></label><label>前缀长度 /<input id="prefix" type="number" min="0" max="32" value="26" required></label><button class="primary">计算网络边界 →</button></form><div class="result" id="subnet-result" aria-live="polite"></div><div class="log" id="subnet-binary"></div><p class="lab-note">模型：标准IPv4前缀计算。/31按照点到点链路用法显示两个端点，/32显示单一主机路由；/0等结果是数学地址范围，不代表其中每个地址都能分配给普通主机。未执行实际网络探测。</p></section>`}
function ipNum(s){if(!/^\d{1,3}(\.\d{1,3}){3}$/.test(s))throw Error('请输入四段十进制IPv4地址，例如192.168.10.130。');let a=s.split('.').map(Number);if(a.some(n=>n>255))throw Error('IPv4 每段必须在0到255之间。');return a.reduce((v,n)=>v*256+n,0)>>>0}function numIP(n){return [24,16,8,0].map(b=>(n>>>b)&255).join('.')}
function calcSubnet(ip,p){let n=ipNum(ip);if(!Number.isInteger(p)||p<0||p>32)throw Error('前缀长度必须为0到32的整数。');let size=2**(32-p),net=Math.floor(n/size)*size,last=net+size-1,mask=p===0?0:(0xffffffff<<(32-p))>>>0;return {ip:n,p,mask,net,last,size,usable:p===32?1:p===31?2:size-2,first:p>=31?net:net+1,end:p>=31?last:last-1}}
function doSubnet(){try{let r=calcSubnet($('#ip').value.trim(),Number($('#prefix').value));$('#subnet-result').classList.remove('error');$('#subnet-result').innerHTML=`<div class="result-grid">${[['网络地址',numIP(r.net)+' / '+r.p],['子网掩码',numIP(r.mask)],[r.p>=31?'末地址（非广播）':'广播地址',numIP(r.last)],['地址总数',r.size.toLocaleString()],['主机/端点范围',numIP(r.first)+' – '+numIP(r.end)],['主机/端点数',r.usable.toLocaleString()]].map(([k,v])=>`<div><small>${k}</small><b>${v}</b></div>`).join('')}</div>`;let bin=n=>[24,16,8,0].map(b=>((n>>>b)&255).toString(2).padStart(8,'0')).join('.');$('#subnet-binary').textContent=`IP    ${bin(r.ip)}\nMASK  ${bin(r.mask)}\nAND   ${bin(r.net)}\n\n${r.p===31?'点到点 /31：两端地址均可用，不保留传统网络/广播地址。':r.p===32?'主机路由 /32：只标识一个地址。':'主机位归零得到网络地址，主机位全一得到广播地址。'}`}catch(e){$('#subnet-result').classList.add('error');$('#subnet-result').textContent=e.message;$('#subnet-binary').textContent='请修正输入后重新计算。'}}
let sw={mac:{},step:0,arp:{},logs:[]};const hostMAC={A:'02:00:00:00:00:0A',B:'02:00:00:00:00:0B',C:'02:00:00:00:00:0C'};
function switchHTML(){sw={mac:{},step:0,arp:{},logs:[]};return `<section class="experiment"><h2>三台终端，一张会学习的表。</h2>${flow([['主机 A','端口 1 · .10'],['交换机 SW1','VLAN 10'],['主机 B / C','端口 2 / 3 · .20 / .30']])}<div class="lab-controls"><label>发送方<select id="sw-src"><option>A</option><option>B</option><option>C</option></select></label><label>接收方<select id="sw-dst"><option>B</option><option>A</option><option>C</option></select></label><button class="primary" id="send-frame">发送单播帧</button><button class="secondary" id="send-arp">逐步 ARP 解析</button><button class="secondary" id="sw-reset">重置表项</button></div><p class="sub">单播模式允许直接构造目的MAC；ARP模式第一次发送请求，下一次发送响应。可观察源MAC学习与目的MAC查表的区别。</p><div class="table-wrap"><table><thead><tr><th>VLAN</th><th>学习到的 MAC</th><th>端口 / 终端</th></tr></thead><tbody id="mac-table"></tbody></table></div><div class="log" id="sw-log" aria-live="polite">MAC表为空。先发送 A → B，观察泛洪。</div><p class="lab-note">模型：三端口都属于VLAN10，全部可转发；不模拟老化、STP、安全策略、帧错误与实际时序。ARP假设三台IPv4终端处于同一/24，交换机只按源MAC学习。重置同时清空ARP缓存。</p></section>`}
function updateSW(){let entries=Object.entries(sw.mac);$('#mac-table').innerHTML=entries.length?entries.map(([host,port])=>`<tr><td>10</td><td>${hostMAC[host]}</td><td>${port} / ${host}</td></tr>`).join(''):'<tr><td colspan="3">尚未学习任何地址</td></tr>';$('#sw-log').textContent=sw.logs.slice(-8).join('\n')||'MAC表为空。先发送 A → B，观察泛洪。'}
function frame(src,dst,type='单播'){let port=h=>h.charCodeAt(0)-64;sw.mac[src]=port(src);let out=dst==='广播'?['A','B','C'].filter(x=>x!==src).map(port):sw.mac[dst]?[sw.mac[dst]]:['A','B','C'].filter(x=>x!==src).map(port);sw.logs.push(`${++sw.step}. ${type} ${src} → ${dst}：学习 ${src}=端口${port(src)}；${dst==='广播'?'广播泛洪':sw.mac[dst]?'已知单播':'未知单播泛洪'}，出端口 ${out.join('、')}。`);updateSW()}
function sendSW(arp=false){let s=$('#sw-src').value,d=$('#sw-dst').value;if(s===d)return toast('请选择不同的发送方和接收方。');if(!arp){frame(s,d);return}let key=s+d;if(sw.arp[key]===1){frame(d,s,'ARP响应');sw.arp[key]=2;sw.logs.push(`   ${s} 已缓存 ${d} 的MAC，下一帧可发单播。`);updateSW()}else if(sw.arp[key]===2){frame(s,d,'缓存命中后的数据帧')}else{frame(s,'广播',`ARP请求（询问 ${d}）`);sw.arp[key]=1;sw.logs.push(`   ${d} 下一步发送单播ARP响应；再次点击「逐步 ARP 解析」。`);updateSW()}}
function vlanHTML(){return `<section class="experiment"><h2>跟随一帧无标签报文穿过两台交换机。</h2>${flow([['主机 A','无标签发送'],['SW1','Access → Trunk'],['SW2','Trunk → Access'],['主机 B','无标签接收']])}<form id="vlan-form"><div class="lab-controls"><label>A端 Access VLAN<input id="v-a" type="number" min="1" max="4094" value="10" required></label><label>SW1 Trunk PVID<input id="v-p1" type="number" min="1" max="4094" value="1" required></label><label>SW1 允许列表<input id="v-l1" value="10,20" required></label><label>SW2 Trunk PVID<input id="v-p2" type="number" min="1" max="4094" value="1" required></label><label>SW2 允许列表<input id="v-l2" value="10,20" required></label><label>B端 Access VLAN<input id="v-b" type="number" min="1" max="4094" value="10" required></label><button class="primary">推演 A → B →</button></div></form><div class="log" id="vlan-log" aria-live="polite"></div><div class="result" id="vlan-result"></div><p class="lab-note">模型：常见VRP二层Access/Trunk标签处理；所有输入VLAN均已创建、接口up、STP可转发，不模拟VLANIF路由。列表用英文逗号，如1,10,20；不接受范围写法。Trunk出方向VLAN等于PVID时去标签，入方向无标签帧归本端PVID，再检查允许列表。</p></section>`}
function vlanSim(a,p1,l1,p2,l2,b){let log=[`① A无标签帧进入SW1 Access口，归入VLAN ${a}。`];if(!l1.includes(a))return {log:[...log,`② SW1 Trunk未允许VLAN ${a}，丢弃。`],ok:false,msg:'未到达 B：SW1 Trunk允许列表阻断。'};let tagged=a!==p1;log.push(`② SW1 Trunk允许VLAN ${a}，${tagged?'携带VLAN '+a+' 标签':'因VLAN等于PVID而不带标签'}发出。`);let received=tagged?a:p2;log.push(`③ SW2收到${tagged?'标签帧，保留VLAN '+a:'无标签帧，按本端PVID归入VLAN '+p2}。`);if(!l2.includes(received))return {log:[...log,`④ SW2 Trunk未允许VLAN ${received}，丢弃。`],ok:false,msg:'未到达 B：SW2 Trunk允许列表阻断。'};if(received!==b)return {log:[...log,`④ 帧属于VLAN ${received}，B口属于VLAN ${b}，无法二层转发到B。`],ok:false,msg:'未到达 B：帧VLAN与B端口VLAN不同。'};log.push(`④ B的Access口属于VLAN ${b}，去标签后交付B。`);return {log,ok:true,msg:received===a?'单向帧到达 B。继续检查回程与主机IP，才能判断业务互通。':`帧到达 B，但发生VLAN ${a} → ${received} 重分类；PVID不一致有隔离风险。`}}
function doVLAN(){try{let val=id=>{let v=Number($('#'+id).value);if(!Number.isInteger(v)||v<1||v>4094)throw Error('VLAN编号必须是1到4094的整数。');return v};let list=id=>{let raw=$('#'+id).value.trim();if(!/^\d+(\s*,\s*\d+)*$/.test(raw))throw Error('允许列表请使用英文逗号分隔的VLAN编号。');let a=raw.split(',').map(Number);if(a.some(v=>!Number.isInteger(v)||v<1||v>4094))throw Error('列表中VLAN编号必须为1到4094。');return a};let r=vlanSim(val('v-a'),val('v-p1'),list('v-l1'),val('v-p2'),list('v-l2'),val('v-b'));$('#vlan-log').textContent=r.log.join('\n');$('#vlan-result').textContent=r.msg;$('#vlan-result').classList.toggle('error',!r.ok)}catch(e){$('#vlan-log').textContent='输入未通过校验。';$('#vlan-result').classList.add('error');$('#vlan-result').textContent=e.message}}
let routeRows=[];const initialRoutes=()=>[{network:'0.0.0.0/0',pref:60,cost:0,next:'10.0.0.1',proto:'Static'},{network:'10.0.0.0/8',pref:10,cost:20,next:'10.0.1.1',proto:'OSPF'},{network:'10.1.0.0/16',pref:60,cost:0,next:'10.0.2.1',proto:'Static'},{network:'10.1.2.0/24',pref:100,cost:0,next:'10.0.3.1',proto:'Static'}];
function routeHTML(){routeRows=initialRoutes();return `<section class="experiment"><h2>最长前缀，先于优先级。</h2><form id="route-select" class="lab-controls"><label>目的IPv4地址<input id="route-dst" value="10.1.2.99" required></label><button class="primary">开始查表 →</button><button type="button" class="secondary" id="route-reset">恢复示例</button></form><div class="table-wrap"><table><thead><tr><th>网络前缀</th><th>来源</th><th>优先级</th><th>Cost</th><th>下一跳</th><th>操作</th></tr></thead><tbody id="route-table"></tbody></table></div><details style="margin-top:20px"><summary style="cursor:pointer;color:var(--green)">添加候选路由</summary><form id="route-add" class="lab-controls"><label>前缀<input id="r-net" value="10.1.2.0/24" required></label><label>协议<select id="r-proto"><option>Static</option><option>OSPF</option></select></label><label>优先级<input id="r-pref" type="number" min="1" max="255" value="60" required></label><label>Cost<input id="r-cost" type="number" min="0" max="65535" value="0" required></label><label>下一跳<input id="r-next" value="10.0.4.1" required></label><button class="secondary">加入候选表</button></form></details><div class="result" id="route-result" aria-live="polite"></div><p class="lab-note">模型：候选路由的下一跳均可达；先最长前缀，再同前缀最低优先级；同优先级且同协议时比较cost。不同协议优先级被人为设成相同时，本模型提示需设备决胜规则，不擅自跨协议比较cost。完全相同的最佳项显示等价候选，是否安装ECMP取决于设备能力。未模拟PBR、递归、BGP选路及收敛。</p></section>`}
function selectRoute(dst,rows){let ip=ipNum(dst);let match=rows.map((r,i)=>{let [n,p]=r.network.split('/');let z=calcSubnet(n,Number(p));return {...r,i,p:z.p,net:z.net,last:z.last}}).filter(r=>ip>=r.net&&ip<=r.last);if(!match.length)return {match:[],best:[]};let max=Math.max(...match.map(x=>x.p)),longest=match.filter(x=>x.p===max),pref=Math.min(...longest.map(x=>x.pref)),chosen=longest.filter(x=>x.pref===pref);if(new Set(chosen.map(x=>x.proto)).size>1)return {match,best:chosen,ambiguous:true};let cost=Math.min(...chosen.map(x=>x.cost));return {match,best:chosen.filter(x=>x.cost===cost)}}
function renderRoutes(){$('#route-table').innerHTML=routeRows.length?routeRows.map((r,i)=>`<tr><td>${r.network}</td><td>${r.proto}</td><td>${r.pref}</td><td>${r.cost}</td><td>${r.next}</td><td><button class="secondary" data-remove-route="${i}" aria-label="删除路由${i+1}">删除</button></td></tr>`).join(''):'<tr><td colspan="6">路由表为空</td></tr>';doRoute()}
function doRoute(){try{let r=selectRoute($('#route-dst').value.trim(),routeRows);$('#route-result').classList.toggle('error',!r.best.length||r.ambiguous);$('#route-result').textContent=r.best.length?(r.ambiguous?`最长前缀及优先级相同，但来自不同协议；需查目标设备协议决胜规则。候选：${r.best.map(x=>x.proto+' via '+x.next).join('；')}`:`匹配 ${r.match.length} 条路由 → 最长前缀 /${r.best[0].p} → 同前缀优先级 ${r.best[0].pref} → ${r.best.length>1?'等价候选：':'选择：'}${r.best.map(x=>x.network+' via '+x.next+'（'+x.proto+'）').join('；')}`):'没有匹配路由，也没有可用默认路由：本模型丢弃该报文。'}catch(e){$('#route-result').classList.add('error');$('#route-result').textContent=e.message}}

function bindDiagram(id){if(id==='subnet'){$('#subnet-form').onsubmit=e=>{e.preventDefault();doSubnet()};doSubnet()}
if(id==='switch'){$('#send-frame').onclick=()=>sendSW();$('#send-arp').onclick=()=>sendSW(true);$('#sw-reset').onclick=()=>{sw={mac:{},step:0,arp:{},logs:[]};updateSW()};updateSW()}
if(id==='vlan'){$('#vlan-form').onsubmit=e=>{e.preventDefault();doVLAN()};doVLAN()}
if(id==='route'){$('#route-select').onsubmit=e=>{e.preventDefault();doRoute()};$('#route-reset').onclick=()=>{routeRows=initialRoutes();renderRoutes()};$('#route-table').onclick=e=>{let b=e.target.closest('[data-remove-route]');if(b){routeRows.splice(Number(b.dataset.removeRoute),1);renderRoutes()}};$('#route-add').onsubmit=e=>{e.preventDefault();try{let raw=$('#r-net').value.trim();if(!/^\d{1,3}(\.\d{1,3}){3}\/\d{1,2}$/.test(raw))throw Error('请使用有效的IPv4前缀，如10.1.2.0/24。');let [ip,p]=raw.split('/'),z=calcSubnet(ip,Number(p));ipNum($('#r-next').value.trim());let pref=Number($('#r-pref').value),cost=Number($('#r-cost').value);if(!Number.isInteger(pref)||pref<1||pref>255||!Number.isInteger(cost)||cost<0||cost>65535)throw Error('优先级为1–255整数，cost为0–65535整数。');routeRows.push({network:numIP(z.net)+'/'+z.p,pref,cost,next:$('#r-next').value.trim(),proto:$('#r-proto').value});renderRoutes();toast('已按网络边界加入候选路由')}catch(err){toast(err.message)}};renderRoutes()}
}
window.ICTModels={ipNum,numIP,calcSubnet,vlanSim,selectRoute};
